examples.script:
Set Variable [ $r ; Value: Let ( [
// take it from source container field
Container = ContainerField;
// now check what's inside
types = MBS( "Container.GetTypes"; Container );
// has PDF content?
Container = If(Position(types; "PDF "; 1; 1) > 0;
// extract PDF part
   MBS( "Container.ExtractStream"; ContainerField; "PDF "; "test.pdf"; "PDF " ); 
// otherwise use container as is
   Container);
// now make URL
result = MBS("Container.GetDataURL"; Container)
];result) ]

Set Variable [ $r ; Value: MBS( "MongoDB.UpdateOne"; $mongo; 
// we select record with ID field
JSONSetElement ( "{}" ; "ID" ; Assets::PrimaryKey ; JSONString );
// and here pass whole record including all fields we like to move
JSONSetElement ( "{}" ; "$set" ; Assets::JSON ; JSONObject );
// and here allow to insert, if record is new
JSONSetElement ( "{}" ; "upsert" ; True ; JSONBoolean )) ]

